from decimal import Decimal, ROUND_HALF_UP, localcontext
from typing import Any


_CENTS = Decimal("0.01")


def _decimal(value: Any) -> Decimal:
    """Apply legacy NVL(x, 0) numeric behavior for supplied numeric fields."""
    if value is None or (isinstance(value, str) and value.strip() == ""):
        return Decimal("0")
    if isinstance(value, Decimal):
        return value
    # str(float) preserves the caller-visible decimal value rather than its
    # underlying binary representation.
    return Decimal(str(value))


def _cents(value: Decimal) -> Decimal:
    """Round monetary values half-up to two decimal places."""
    return value.quantize(_CENTS, rounding=ROUND_HALF_UP)


def recompute(order: dict, lines: list[dict]) -> tuple[dict, list[dict], list]:
    """Recompute one eligible order's live-line extensions and total."""
    new_order = dict(order)
    new_lines = [dict(line) for line in lines]

    if order.get("DEL_FLG") == "Y" or order.get("STAT_CD") == "X":
        return new_order, new_lines, []

    with localcontext() as context:
        context.prec = 50

        total = Decimal("0")
        for original_line, new_line in zip(lines, new_lines):
            if original_line.get("DEL_FLG") == "Y":
                continue

            extension = _cents(
                _decimal(original_line.get("QTY"))
                * _decimal(original_line.get("UNIT_PRC"))
            )
            new_line["EXT_AMT"] = float(extension)
            total += extension

        discounted = _cents(
            total * (Decimal("100") - _decimal(order.get("DISC_PCT"))) / Decimal("100")
        )
        new_order["TOT_AMT"] = float(discounted)

        audits = []
        if _decimal(order.get("TOT_AMT")) != discounted:
            audits.append(("ORD_RETOTAL", order.get("ORD_ID")))

    return new_order, new_lines, audits
